package com.peopleai.candidates.model;
import jakarta.persistence.*;import jakarta.validation.constraints.NotBlank;
@Entity @Table(name="candidates") public class Candidate {@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@NotBlank private String name;@NotBlank private String role;private Integer score;private String location;private String email;private String status="New";protected Candidate(){}public Long getId(){return id;}public String getName(){return name;}public void setName(String x){name=x;}public String getRole(){return role;}public void setRole(String x){role=x;}public Integer getScore(){return score;}public void setScore(Integer x){score=x;}public String getLocation(){return location;}public void setLocation(String x){location=x;}public String getEmail(){return email;}public void setEmail(String x){email=x;}public String getStatus(){return status;}public void setStatus(String x){status=x;}}
